import{_ as a,o as t,c as o,ae as i}from"./chunks/framework.8rYXDNLJ.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md"}'),r={name:"reference/faq.md"};function n(s,e,l,d,h,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="is-portman-free" tabindex="-1">Is Portman free? <a class="header-anchor" href="#is-portman-free" aria-label="Permalink to &quot;Is Portman free?&quot;">​</a></h3><p>Yes! Portman is currently free during the beta period.</p><h3 id="does-it-work-on-intel-macs" tabindex="-1">Does it work on Intel Macs? <a class="header-anchor" href="#does-it-work-on-intel-macs" aria-label="Permalink to &quot;Does it work on Intel Macs?&quot;">​</a></h3><p>Currently, the desktop app is built for Apple Silicon only. The MCP server works on both Intel and Apple Silicon.</p><h3 id="is-my-data-sent-anywhere" tabindex="-1">Is my data sent anywhere? <a class="header-anchor" href="#is-my-data-sent-anywhere" aria-label="Permalink to &quot;Is my data sent anywhere?&quot;">​</a></h3><p>No. Portman works entirely locally. No data is sent to any external servers.</p><hr><h2 id="desktop-app" tabindex="-1">Desktop App <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop App&quot;">​</a></h2><h3 id="why-do-i-see-a-security-warning-on-first-launch" tabindex="-1">Why do I see a security warning on first launch? <a class="header-anchor" href="#why-do-i-see-a-security-warning-on-first-launch" aria-label="Permalink to &quot;Why do I see a security warning on first launch?&quot;">​</a></h3><p>Portman is not signed with an Apple Developer certificate ($99/year). This is common for free/indie macOS apps. See <a href="/portman/docs/guide/installation.html">Installation</a> for how to bypass the warning safely.</p><h3 id="where-is-my-data-stored" tabindex="-1">Where is my data stored? <a class="header-anchor" href="#where-is-my-data-stored" aria-label="Permalink to &quot;Where is my data stored?&quot;">​</a></h3><p>Labels are stored in <code>~/.local/share/portman/labels.sqlite</code>.</p><h3 id="how-do-i-completely-uninstall-portman" tabindex="-1">How do I completely uninstall Portman? <a class="header-anchor" href="#how-do-i-completely-uninstall-portman" aria-label="Permalink to &quot;How do I completely uninstall Portman?&quot;">​</a></h3><ol><li>Delete <code>Portman.app</code> from Applications</li><li>Remove data: <code>rm -rf ~/.local/share/portman</code></li></ol><hr><h2 id="mcp-server" tabindex="-1">MCP Server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to &quot;MCP Server&quot;">​</a></h2><h3 id="what-ai-assistants-are-supported" tabindex="-1">What AI assistants are supported? <a class="header-anchor" href="#what-ai-assistants-are-supported" aria-label="Permalink to &quot;What AI assistants are supported?&quot;">​</a></h3><p>Any MCP-compatible client:</p><ul><li>Claude Desktop</li><li>Claude Code</li><li>Antigravity (Gemini)</li><li>Other MCP clients</li></ul><h3 id="do-i-need-the-desktop-app-to-use-mcp" tabindex="-1">Do I need the desktop app to use MCP? <a class="header-anchor" href="#do-i-need-the-desktop-app-to-use-mcp" aria-label="Permalink to &quot;Do I need the desktop app to use MCP?&quot;">​</a></h3><p>No. The MCP server (<code>portman-mcp</code>) works independently.</p><h3 id="how-do-i-update-the-mcp-server" tabindex="-1">How do I update the MCP server? <a class="header-anchor" href="#how-do-i-update-the-mcp-server" aria-label="Permalink to &quot;How do I update the MCP server?&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> portman-mcp@latest</span></span></code></pre></div><p>Or reinstall with <code>@latest</code> in your MCP config.</p><hr><h2 id="vibe-coding" tabindex="-1">Vibe Coding <a class="header-anchor" href="#vibe-coding" aria-label="Permalink to &quot;Vibe Coding&quot;">​</a></h2><h3 id="what-is-vibe-coding" tabindex="-1">What is Vibe Coding? <a class="header-anchor" href="#what-is-vibe-coding" aria-label="Permalink to &quot;What is Vibe Coding?&quot;">​</a></h3><p>Vibe Coding is AI-assisted development where you collaborate with AI to write code rapidly. This often involves spinning up multiple services, which can lead to port conflicts.</p><h3 id="how-does-portman-help-with-vibe-coding" tabindex="-1">How does Portman help with Vibe Coding? <a class="header-anchor" href="#how-does-portman-help-with-vibe-coding" aria-label="Permalink to &quot;How does Portman help with Vibe Coding?&quot;">​</a></h3><ul><li><strong>Visibility:</strong> See all running ports at a glance</li><li><strong>Conflict resolution:</strong> Quickly identify what&#39;s using a port</li><li><strong>AI integration:</strong> Let Claude manage ports for you via MCP</li><li><strong>Find free ports:</strong> Instantly discover available ports for new services</li></ul>',32)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
